export async function withIp4rApi(work: (fixture: { client: pg.Client; connection: DatabaseConnection<typeof relations>; api: typeof ip4rApi }) => Promise<void>, proofCaseId?: string) {
  await withExtensionDatabase(async (url) => {
    const client = new pg.Client({ connectionString: url });
    await client.connect();
    try {
      const server = await client.query("select current_setting('server_version_num')::int version");
      assert.equal(Math.floor(server.rows[0].version / 10000), 18);
      const available = await client.query("select name from pg_available_extension_versions where name='ip4r' and version='2.4'");
      assert.notEqual(available.rowCount, 0, "The PostgreSQL 18 fixture must include the ip4r 2.4 binary");
      await client.query(`create schema ${ip4rNamespace}; create extension ip4r with schema ${ip4rNamespace} version '2.4'`);
      if (proofCaseId) await observeExtensionProofDatabase(url, proofCaseId, "ip4r");
      for (const statement of await migrationStatements(await emptySnapshot("app"), await createSnapshot(ip4rManaged))) await client.query(statement);
      // SQL keyword bit and untypmodded bit columns are bit(1). ip4r 2.4 ip4/ipaddress bit casts need exactly 32 bits; ip6 needs exactly 128.
      // ip4r 2.4 / and *_net_mask require a contiguous netmask (ip4_valid_netmask / ip6_valid_netmask), not a second host address.
      const bit = `pg_catalog.${pg.escapeIdentifier("bit")}`;
      const ip4Bits = "11000000000000000000001000001010";
      const ip6Bits = `00100000000000010000110110111000${"0".repeat(80)}0000000000010000`;
      await client.query(`create table portable_ip4r_inputs(ip4_a ${ip4rNamespace}.ip4, ip4_b ${ip4rNamespace}.ip4, ip4_c ${ip4rNamespace}.ip4, ip4_mask ${ip4rNamespace}.ip4, ip4r_a ${ip4rNamespace}.ip4r, ip4r_b ${ip4rNamespace}.ip4r, ip4r_c ${ip4rNamespace}.ip4r, ip6_a ${ip4rNamespace}.ip6, ip6_b ${ip4rNamespace}.ip6, ip6_c ${ip4rNamespace}.ip6, ip6_mask ${ip4rNamespace}.ip6, ip6r_a ${ip4rNamespace}.ip6r, ip6r_b ${ip4rNamespace}.ip6r, ip6r_c ${ip4rNamespace}.ip6r, ipaddress_a ${ip4rNamespace}.ipaddress, ipaddress_b ${ip4rNamespace}.ipaddress, ipaddress_c ${ip4rNamespace}.ipaddress, ipaddress_mask ${ip4rNamespace}.ipaddress, iprange_a ${ip4rNamespace}.iprange, iprange_b ${ip4rNamespace}.iprange, iprange_c ${ip4rNamespace}.iprange, bool_a bool, bool_b bool, int4_v int4, int8_v int8, float8_v float8, numeric_v numeric, text_v text, text6_v text, bytea_v bytea, bytea6_v bytea, inet_v inet, inet6_v inet, cidr_v cidr, cidr6_v cidr, bit_v ${bit}(32), bit6_v ${bit}(128), varbit_v varbit, varbit6_v varbit)`);
      await client.query(`insert into portable_ip4r_inputs values (${ip4rNamespace}.ip4('192.0.2.10'), ${ip4rNamespace}.ip4('192.0.2.20'), ${ip4rNamespace}.ip4('192.0.2.30'), ${ip4rNamespace}.ip4('255.255.255.0'), ${ip4rNamespace}.ip4r('192.0.2.0/24'), ${ip4rNamespace}.ip4r('192.0.2.0/25'), ${ip4rNamespace}.ip4r('192.0.2.0/26'), ${ip4rNamespace}.ip6('2001:db8::10'), ${ip4rNamespace}.ip6('2001:db8::20'), ${ip4rNamespace}.ip6('2001:db8::30'), ${ip4rNamespace}.ip6('ffff:ffff::'), ${ip4rNamespace}.ip6r('2001:db8::/32'), ${ip4rNamespace}.ip6r('2001:db8::/48'), ${ip4rNamespace}.ip6r('2001:db8::/64'), ${ip4rNamespace}.ipaddress('192.0.2.10'), ${ip4rNamespace}.ipaddress('192.0.2.20'), ${ip4rNamespace}.ipaddress('2001:db8::10'), ${ip4rNamespace}.ipaddress('255.255.255.0'), ${ip4rNamespace}.iprange('192.0.2.0/24'), ${ip4rNamespace}.iprange('192.0.2.0/25'), ${ip4rNamespace}.iprange('2001:db8::/32'), true, false, 8, 1, 1, 1, '192.0.2.10', '2001:db8::10', E'\\\\xC000020A', E'\\\\x20010db8000000000000000000000010', '192.0.2.10'::inet, '2001:db8::10'::inet, '192.0.2.0/24'::cidr, '2001:db8::/32'::cidr, B'${ip4Bits}'::${bit}(32), B'${ip6Bits}'::${bit}(128), B'${ip4Bits}'::varbit, B'${ip6Bits}'::varbit)`);
      const connection = await connectDatabase({ schema: ip4rManaged, relations, connectionString: url });
      try { await work({ client, connection, api: ip4rApi }); } finally { await connection.close(); }
    } finally { await client.end(); }
  });
}

